const COLS = [{"key":"billing_account_id","label":"Billing Account ID"},{"key":"vendor","label":"Vendor"},{"key":"billing_id","label":"Billing ID"},{"key":"service_account_id","label":"Service Account ID"},{"key":"meter_id","label":"Meter ID"},{"key":"utility","label":"Utility"},{"key":"type","label":"Type"},{"key":"last_bill","label":"Last Bill"}];

function App() {
  const [model, setModel] = useState(appsmith.model || {});
  const [q, setQ] = useState("");
  const [pair, setPair] = useState("nopair");
  const [sel, setSel] = useState({});
  const [sortKey, setSortKey] = useState("billing_account_id");
  const [sortDir, setSortDir] = useState("asc");

  useEffect(() => {
    const update = () => setModel({ ...(appsmith.model || {}) });
    update();
    if (typeof appsmith.onModelChange === "function") appsmith.onModelChange(update);
    const id = setInterval(update, 400);
    return () => clearInterval(id);
  }, []);

  const data = (model && model.data) || [];

  const filtered = useMemo(() => {
    const term = q.trim().toLowerCase();
    let list = data;
    if (pair === "nopair") list = list.filter((r) => r.pair_status === "Need Pair");
    else if (pair === "paired") list = list.filter((r) => r.pair_status === "Pair");
    if (term) list = list.filter((r) => String(r.site || "").toLowerCase().indexOf(term) !== -1
      || COLS.some((c) => { const v = r[c.key]; return v != null && String(v).toLowerCase().indexOf(term) !== -1; }));
    return list;
  }, [data, q, pair]);

  // group: site -> utility -> rows, preserving query order
  const groups = useMemo(() => {
    const bySite = new Map();
    filtered.forEach((r) => {
      const s = r.site == null ? "" : String(r.site);
      if (!bySite.has(s)) bySite.set(s, { site: s, location_id: r.location_id, utils: new Map() });
      const g = bySite.get(s);
      const u = r.utility == null ? "" : String(r.utility);
      if (!g.utils.has(u)) g.utils.set(u, []);
      g.utils.get(u).push(r);
    });
    return Array.from(bySite.values());
  }, [filtered]);

  const onSort = (k) => { if (k === sortKey) setSortDir(sortDir === "asc" ? "desc" : "asc"); else { setSortKey(k); setSortDir("asc"); } };
  const sortRows = (rows) => {
    const list = rows.slice();
    list.sort((a, b) => {
      const av = (a[sortKey] == null ? "" : String(a[sortKey])), bv = (b[sortKey] == null ? "" : String(b[sortKey]));
      return sortDir === "asc" ? av.localeCompare(bv) : bv.localeCompare(av);
    });
    return list;
  };

  const toggle = (id) => setSel((s) => { const n = { ...s }; if (n[id]) delete n[id]; else n[id] = true; return n; });
  const openVAs = (g) => { appsmith.updateModel({ selectedLocationId: g.location_id, selectedLocationSite: g.site }); if (typeof appsmith.triggerEvent === "function") appsmith.triggerEvent("onOpenLocation"); };

  if (model.isLoading) return React.createElement("div", { className: "skel" }, "Loading virtual accounts...");

  const arrows = (k) => React.createElement("span", { className: "sort" },
    React.createElement("span", { className: (sortKey === k && sortDir === "asc") ? "active" : "" }, "\u25B2"),
    React.createElement("span", { className: (sortKey === k && sortDir === "desc") ? "active" : "" }, "\u25BC"));

  const headRow = React.createElement("tr", null,
    React.createElement("th", { className: "chk" }, ""),
    COLS.map((c) => React.createElement("th", { key: c.key, onClick: () => onSort(c.key) }, c.label, arrows(c.key))));

  const cell = (r, key) => {
    if (key === "last_bill") return r.last_bill ? React.createElement("span", { className: "datelink" }, r.last_bill) : "";
    const v = r[key];
    return v == null ? "" : String(v);
  };

  const body = groups.length === 0
    ? React.createElement("div", { className: "empty" }, "No unpaired virtual accounts")
    : groups.map((g, gi) => React.createElement("div", { key: "g" + gi, className: "sitewrap" },
        React.createElement("div", { className: "site" },
          React.createElement("h3", null, g.site),
          React.createElement("a", { onClick: () => openVAs(g) }, "Virtual Accounts")),
        React.createElement("table", { className: "tbl" },
          React.createElement("thead", null, headRow),
          React.createElement("tbody", null,
            Array.from(g.utils.entries()).map(([util, rows], ui) => [
              React.createElement("tr", { key: "u" + gi + "_" + ui, className: "utilrow" },
                React.createElement("td", { colSpan: COLS.length + 1 }, util)),
              sortRows(rows).map((r, ri) => React.createElement("tr", { key: "r" + gi + "_" + ui + "_" + ri, className: "datarow" },
                React.createElement("td", { className: "chk" },
                  React.createElement("input", { type: "checkbox", className: "cbx", checked: !!sel[r.va_id], onChange: () => toggle(r.va_id) })),
                COLS.map((c) => React.createElement("td", { key: c.key }, cell(r, c.key)))))
            ]))))
      );

  return React.createElement("div", { className: "wrap" },
    React.createElement("div", { className: "topbar" },
      React.createElement("div", { className: "search" },
        React.createElement("input", { type: "text", placeholder: "Search for Location", value: q, onChange: (e) => setQ(e.target.value) })),
      React.createElement("div", { className: "pairtoggle" },
        React.createElement("a", { className: pair === "nopair" ? "active" : "", onClick: () => setPair("nopair") }, "No Pair"),
        React.createElement("a", { className: pair === "paired" ? "active" : "", onClick: () => setPair("paired") }, "Pair"))),
    React.createElement("div", { className: "scroll" }, body));
}

ReactDOM.render(React.createElement(App, null), document.getElementById("root"));

